    # 1. If we're at a center position, use center value
    # 2. If column has a center in a different row (vertical band from different center), use that
    # 3. If row has a center but we're not at it and column has no center, use horizontal band
    # 4. Otherwise 0

    if center_in_col is not None:
        # Vertical band from a DIFFERENT center wins
        return center_in_col
    elif center_at_this_pos is not None:
        # We're at a center position
        return center_at_this_pos
    elif center_in_row is not None and center_in_col is None:
        # Center row but not at center, and no vertical band
        return center_in_row
    else:
